// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MultiplicatorX3} from "../src/MultiplicatorX3.sol";

contract InvMutTest is Test {
    MultiplicatorX3 c;
    function setUp() public { c = new MultiplicatorX3(); }
    function testFuzz_property(uint256 amount, address actor, address adr) public {
        vm.assume(actor != address(0));
        vm.assume(adr != address(0));
        amount = bound(amount, 1, type(uint256).max / 4);
        vm.deal(actor, amount);
        vm.prank(actor);
        bool ok;
        try c.multiplicate{value: amount}(adr) {
            ok = true;
        } catch {
            ok = false;
        }
        // Reference: the drain transfer (balance+msg.value > balance, since msg.value
        // is already in balance) always fails, so the call must revert.
        // Mutant: transfers only msg.value (always affordable), so the call succeeds.
        assertTrue(!ok, "multiplicate must revert when draining more than the balance");
    }
}
